await bash('cd /workspace && python3 - <<'EOF'
import random, math

def run(strategy, seed=11, N=500, D=240):
    rng = random.Random(seed)
    stab=[3.0]*N
    if strategy=="sm2":
        st=[dict(ef=2.5,reps=0,interval=1) for _ in range(N)]
        def upd(c,q):
            if q<3: c.reps=0; c.interval=1; return
            c.ef=max(1.3,c.ef+0.1-(5-q)*(0.08+(5-q)*0.02))
            if c.reps==0: c.interval=1
            elif c.reps==1: c.interval=6
            else: c.interval=round(c.interval*c.ef)
            c.reps+=1
    else:
        L=[1,3,7,14,30,60]
        st=[dict(rung=0) for _ in range(N)]
        def upd(c,q):
            # schedule at CURRENT rung, then move
            iv=L[c.rung]
            if q<3: c.rung=max(0,c.rung-1)
            else: c.rung=min(len(L)-1,c.rung+1)
            return iv
    nd=[1]*N; lr=[None]*N; total=0
    for day in range(1,D+1):
        for i in range(N):
            if nd[i]!=day: continue
            el=day-lr[i] if lr[i] is not None else 0
            ok=rng.random()<math.exp(-el/stab[i])
            if ok:
                q=4 if rng.random()<0.5 else 5
                stab[i]*=1.9
            else:
                q=1; stab[i]=3.0
            if strategy=="sm2":
                upd(st[i],q); iv=st[i]["interval"]
            else:
                iv=upd(st[i],q)
            lr[i]=day; nd[i]=day+max(iv,1); total+=1
    ret=sum(1 for i in range(N) if rng.random()<math.exp(-(D-lr[i])/stab[i]))/N
    exp_ret=sum(math.exp(-(D-lr[i])/stab[i]) for i in range(N))/N
    print(f"{strategy:7s} total={total:6d} retention={ret:.4f} expected={exp_ret:.4f}")

for s in ("sm2","ladder"):
    for seed in (11, 7, 42):
        run(s, seed)
